import React, { useState } from 'react';
import classes from './SocialMedia.module.scss'; // Создайте SocialMediaDropdown.module.scss

const SocialMediaDropdown = () => {
  const [isOpen, setIsOpen] = useState(false);

  const toggleDropdown = () => {
    setIsOpen(!isOpen);
  };

  return (
    <div className={classes.dropdown}>
      <button className={classes.dropdownButton} onClick={toggleDropdown}>
        Социальные сети {/* Здесь можно добавить иконку */}
      </button>
      <ul className={`${classes.dropdownMenu} ${isOpen ? classes.active : ''}`}>
        <li>
          <a href="https://vk.com/" target="_blank" rel="noopener noreferrer">
            ВКонтакте
          </a>
        </li>
        <li>
          <a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer">
            Instagram
          </a>
        </li>
        <li>
          <a href="https://www.facebook.com/" target="_blank" rel="noopener noreferrer">
            Facebook
          </a>
        </li>
        {/* Добавьте другие ссылки на социальные сети */}
      </ul>
    </div>
  );
};

export default SocialMediaDropdown;
